import { readFileSync, writeFileSync, renameSync } from "node:fs";
import { randomUUID } from "node:crypto";

export function createStore(file) {
  let books = [];
  try {
    books = JSON.parse(readFileSync(file, "utf8"));
  } catch {}

  function save() {
    const tmp = file + ".tmp";
    writeFileSync(tmp, JSON.stringify(books, null, 2));
    renameSync(tmp, file);
  }

  return {
    list() {
      return {
        reading: books.filter((b) => !b.finishedAt),
        finished: books
          .filter((b) => b.finishedAt)
          .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt)),
      };
    },
    get(id) {
      return books.find((b) => b.id === id) ?? null;
    },
    add({ title, author, notes }) {
      if (!title?.trim()) throw new Error("Title is required");
      const book = {
        id: randomUUID().slice(0, 8),
        title: title.trim(),
        author: (author ?? "").trim(),
        notes: (notes ?? "").trim(),
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      save();
      return book;
    },
    finish(id) {
      const book = this.get(id);
      if (!book) return null;
      book.finishedAt = new Date().toISOString();
      save();
      return book;
    },
  };
}

import { createServer } from "node:http";
import { createStore } from "./store.js";

const PORT = process.env.PORT ?? 3000;
const store = createStore(new URL("./books.json", import.meta.url).pathname);

const esc = (s = "") =>
  s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

const page = (title, body) => `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)} — Book Tracker</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; }
  a { color: #06c; }
  ul { padding-left: 1.25rem; }
  li { margin-bottom: .35rem; }
  .meta { color: #666; font-size: .9rem; }
  form { border: 1px solid #ddd; border-radius: 8px; padding: 1rem; margin-top: 1.5rem; }
  label { display: block; margin-top: .6rem; font-weight: 600; }
  input, textarea { width: 100%; box-sizing: border-box; padding: .4rem; margin-top: .2rem; }
  button { margin-top: .8rem; padding: .45rem 1rem; cursor: pointer; }
  .finish { background: none; border: none; color: #06c; text-decoration: underline; padding: 0; font-size: .9rem; }
</style>
</head>
<body>
<h1><a href="/" style="color:inherit;text-decoration:none">Book Tracker</a></h1>
${body}
</body>
</html>`;

const homePage = () => {
  const { reading, finished } = store.list();
  const item = (b) => `
    <li><a href="/books/${b.id}">${esc(b.title)}</a>${b.author ? ` <span class="meta">by ${esc(b.author)}</span>` : ""}
    ${b.finishedAt ? `<span class="meta">— finished ${b.finishedAt.slice(0, 10)}</span>` : `
    <form method="post" action="/books/${b.id}/finish" style="display:inline"><button class="finish">mark finished</button></form>`}
    </li>`;
  return page("Home", `
    <h2>Currently reading (${reading.length})</h2>
    <ul>${reading.map(item).join("") || "<li class='meta'>Nothing yet</li>"}</ul>
    <h2>Finished (${finished.length})</h2>
    <ul>${finished.map(item).join("") || "<li class='meta'>Nothing yet</li>"}</ul>
    <form method="post" action="/books">
      <h2 style="margin-top:0">Add a book</h2>
      <label>Title <input name="title" required></label>
      <label>Author <input name="author"></label>
      <label>Notes <textarea name="notes" rows="3"></textarea></label>
      <button type="submit">Add book</button>
    </form>`);
};

const bookPage = (b) => page(b.title, `
  <h2>${esc(b.title)}</h2>
  <p class="meta">${b.author ? `by ${esc(b.author)} · ` : ""}${b.finishedAt ? `Finished ${b.finishedAt.slice(0, 10)}` : "Currently reading"}</p>
  ${b.notes ? `<h3>Notes</h3><p>${esc(b.notes).replace(/\n/g, "<br>")}</p>` : ""}
  ${b.finishedAt ? "" : `<form method="post" action="/books/${b.id}/finish"><button>Mark as finished</button></form>`}
  <p><a href="/">← Back</a></p>`);

const readBody = (req) =>
  new Promise((resolve) => {
    let data = "";
    req.on("data", (c) => (data += c));
    req.on("end", () => resolve(Object.fromEntries(new URLSearchParams(data))));
  });

createServer(async (req, res) => {
  const url = new URL(req.url, "http://localhost");
  const send = (code, html) => {
    res.writeHead(code, { "content-type": "text/html; charset=utf-8" });
    res.end(html);
  };
  const redirect = (loc) => {
    res.writeHead(303, { location: loc });
    res.end();
  };

  if (req.method === "GET" && url.pathname === "/") return send(200, homePage());

  if (req.method === "POST" && url.pathname === "/books") {
    const body = await readBody(req);
    try {
      const book = store.add(body);
      return redirect(`/books/${book.id}`);
    } catch (e) {
      return send(400, page("Error", `<p>${esc(e.message)}</p><p><a href="/">← Back</a></p>`));
    }
  }

  const bookMatch = url.pathname.match(/^\/books\/([\w-]+)$/);
  if (req.method === "GET" && bookMatch) {
    const book = store.get(bookMatch[1]);
    return book
      ? send(200, bookPage(book))
      : send(404, page("Not found", `<p>Book not found.</p><p><a href="/">← Back</a></p>`));
  }

  const finishMatch = url.pathname.match(/^\/books\/([\w-]+)\/finish$/);
  if (req.method === "POST" && finishMatch) {
    return store.finish(finishMatch[1]) ? redirect("/") : send(404, page("Not found", "<p>Book not found.</p>"));
  }

  send(404, page("Not found", `<p>Not found.</p><p><a href="/">← Back</a></p>`));
}).listen(PORT, () => console.log(`Book tracker running at http://localhost:${PORT}`));

import { test, expect, beforeEach, afterEach } from "vitest";
import { createStore } from "./store.js";
import { rmSync } from "node:fs";

const file = "/tmp/test-books.json";
let store;

beforeEach(() => {
  rmSync(file, { force: true });
  store = createStore(file);
});

afterEach(() => rmSync(file, { force: true }));

test("adds a book and lists it as reading", () => {
  store.add({ title: "Dune", author: "Frank Herbert", notes: "great" });
  const { reading, finished } = store.list();
  expect(reading).toHaveLength(1);
  expect(finished).toHaveLength(0);
  expect(reading[0].title).toBe("Dune");
});

test("requires a title", () => {
  expect(() => store.add({ title: "" })).toThrow();
});

test("marks a book finished and persists across restart", () => {
  const book = store.add({ title: "Dune" });
  store.finish(book.id);

  const reloaded = createStore(file);
  const { reading, finished } = reloaded.list();
  expect(reading).toHaveLength(0);
  expect(finished).toHaveLength(1);
  expect(reloaded.get(book.id).finishedAt).toBeTruthy();
});

test("returns null for unknown book", () => {
  expect(store.get("nope")).toBeNull();
});

